 if(has('projects.progress')&&!['completed','cancelled'].includes(r.status))result+=updateForm('/projects/'+id+'/milestones',r,select('Milestone','code',has('projects.manage')?['survey','design','materials','schedule','installation','inspection','commissioning','handover']:['survey','installation'])+select('Progress','status',has('projects.manage')?['pending','in_progress','done','not_applicable']:['pending','in_progress','done'])+text('Progress notes · visible in customer activity','notes','',true)+field('Supporting record reference · required for inspection, commissioning and handover completion','evidenceReference','',false,'text',200),'Record milestone progress');
