 function extraDetails(kind,r,data){let body='';
 if(data.milestones)body+=section('Recorded milestones · supplied progress',data.milestones.map(m=>`<article class="ops-milestone"><strong>${e(m.code.replaceAll('_',' '))}</strong>${badge(m.status)}<p>${e(m.notes||'')}</p>${m.evidence_reference?`<small>Supporting record: ${e(m.evidence_reference)} · Not independently verified</small>`:''}</article>`).join(''));
 if(data.team)body+=section('Project team',data.team.map(t=>`<p>${e(t.display_name)}</p>`).join(''));
 if(data.lines)body+=section('Purchase lines',data.lines.map(x=>`<article class="purchase-note"><strong>${e(x.name)}</strong><p>Ordered ${qty(x.quantity_milli)} · Received ${qty(x.received_milli)} · Outstanding ${qty(BigInt(x.quantity_milli)-BigInt(x.received_milli))} ${e(x.unit)}</p><p>${x.unit_price_paise===null?'Cost not supplied':money(x.unit_price_paise)+' per '+e(x.unit)}</p></article>`).join(''));
 if(data.movements)body+=section('Stock movement ledger',data.movements.items.map(m=>`<article class="purchase-note"><strong>${e(m.kind)}</strong><p>On-hand change ${qty(m.on_hand_delta)} · Reserved change ${qty(m.reserved_delta)}</p><p>${e(m.reason)}</p><small>${when(m.created_at)}</small></article>`).join('')+pager(data.movements));
 if(data.reservations)body+=section('Order reservations',data.reservations.items.map(x=>`<article class="purchase-note"><p>Remaining ${qty(x.remaining_milli)} · Consumed ${qty(x.consumed_milli)}</p>${has('orders.read')?link(detail('orders',x.order_id),'Open related order','text-link'):''}${has('inventory.manage')&&BigInt(x.remaining_milli)>0n?form('/reservations/'+x.id+'/actions',operation()+select('Movement','action',['consume','release'])+field('Quantity','quantity','',true)+text('Actual movement reason','reason','',true),'Record reservation movement'):''}</article>`).join('')+pager(data.reservations));
 if(data.collections)body+=section('Recorded collections and reversals',data.collections.items.map(x=>`<article class="purchase-note"><strong>${money(x.amount_paise)} · ${e(x.method)}</strong><p>${e(x.external_reference||'No external reference supplied')}</p><p>${e(x.reason)} · ${e(x.collected_on)}</p><small>Manual record · No bank/provider verification</small>${has('finance.reverse')&&!x.reverses_id?form('/collections/'+x.id+'/reverse',operation()+text('Authorized reversal reason · at least 10 characters','reason','',true),'Append full reversal'):''}</article>`).join('')+pager(data.collections));
 if(data.related)for(const [kind,records] of Object.entries(data.related))body+=section('Related '+defs[kind][0].toLowerCase(),records.items.map(x=>summary(kind,x)).join('')+pager(records));
 if(data.quotations)body+=section('Linked quotations and enquiries',data.quotations.items.map(q=>`<p>${link('/distributor/quotation?id='+q.id,e(q.reference)+' · v'+q.version,'text-link')} · ${link('/distributor/enquiry?id='+q.enquiry_id,'Original enquiry','text-link')}</p>`).join('')+pager(data.quotations));return body;
 }
 function recordPage(pth){const kind=p().get('kind'),id=p().get('id')||'',page=p().get('page')||1;if(!defs[kind]||!customer()&&!canRead(kind))return empty('This record is unavailable to your role.');return A().resource(pth,base()+'/record/'+kind+'/'+encodeURIComponent(id)+'?page='+page,data=>{const r=data.record;return `${heading(customer()?'YOUR BUSINESS RECORD':'YOUR COMPANY RECORD',e(r.name||r.title||r.reference),customer()?'Your own commercial and service records. Private company notes and supplier costs are excluded.':'Explicit decisions, recorded history and a clear next action.')}${nav()}<div class="ops-detail"><div>${section('Record details',detailsBody(kind,r,data)+(data.links?.length?'<nav class="purchase-nav" aria-label="Linked records">'+data.links.map(x=>link(detail(x.kind,x.id),e(x.label),'btn secondary')).join('')+'</nav>':''))}${extraDetails(kind,r,data)}${section('Activity history',`<ol class="purchase-timeline">${data.history.items.map(x=>`<li><strong>${e(x.action.replaceAll('_',' '))}</strong><p>${e(x.notes)}</p><small>${when(x.created_at)}</small></li>`).join('')||'<li>No activity yet.</li>'}</ol>`+pager(data.history))}</div><div>${section('Next action',actions(kind,r,data))}${!customer()?documents(kind,r,data):''}</div></div>`;});}
 function documents(kind,r,data){return section('Private notes and document references',`${has(defs[kind][2])?form('/record/'+kind+'/'+r.id+'/notes',text('Internal company note','notes','',true),'Save private note'):''}<h3>Document metadata · uploads unavailable</h3>${data.documents.items.map(d=>`<article class="purchase-note"><strong>${e(d.title)}</strong><p>${e(d.reference)}</p><small>${e(d.document_date||'Date not supplied')}</small><p>${e(d.notes)}</p></article>`).join('')||'<p class="muted">No document references.</p>'}${pager(data.documents)}${has(defs[kind][2])?form('/record/'+kind+'/'+r.id+'/documents',operation()+field('Document title','title','',true)+field('Where the document is held / reference','reference','',true,'text',200)+field('Document date · optional','documentDate','',false,'date')+text('Private document notes','notes'),'Record metadata only'):''}<p class="fine-print">This stores plain-text metadata only. No file is uploaded, hosted or verified.</p>`);}
 function dashboard(pth){return A().resource(pth,base()+'/dashboard',data=>{
 const owner=A().activeCompany?.role==='owner',cards=data.cards||[],hero=cards.filter(c=>['enquiries','quotations','projects','service'].includes(c.kind)),actions=[['crm.manage','/distributor/new?kind=leads','Add lead','users'],['quotations.manage','/distributor/leads','Prepare quotation','file'],['customers.manage','/distributor/new?kind=contacts','Add customer','users'],['members.manage','/distributor/team','Invite employee','users'],['tasks.manage','/distributor/new?kind=tasks','Assign task','check'],['orders.manage','/distributor/new?kind=orders','Create order','box']].filter(([permission])=>has(permission));
 const metric=card=>link(card.kind==='enquiries'?'/distributor/leads':card.kind==='quotations'?'/distributor/quotations':defs[card.kind][3],`<span class="round-icon">${icon(card.kind==='service'?'help':'file')}</span><strong>${card.money?money(card.value):e(card.value)}</strong><span>${e(card.label)}</span>`,'panel ops-metric');
 return `${heading(owner?'YOUR COMPANY CONTROL CENTRE':'YOUR WORKSPACE',owner?'Today in your business.':'My work today.',e(A().activeCompany.name)+' - '+e(A().activeCompany.role_label))}<div class="boss-actions">${actions.map(([,url,label,symbol])=>link(url,icon(symbol)+label,'btn primary')).join('')}${has('company.setup.read')?link('/distributor/setup?step=profile',icon('settings')+'Company setup','btn secondary'):''}</div>${A().feedback()}${has('automation.read')?link('/distributor/automation','Review reminders and delivery failures','btn secondary'):''}${Workspace.firstSteps(data)}<p class="fine-print">Updated ${when(data.asOf)}. ${e(data.scope||'Your authorized company records.')}</p><div class="ops-metrics">${(hero.length?hero:cards.slice(0,4)).map(metric).join('')}</div>${data.outstanding!==null&&data.outstanding!==undefined?section('Collections to follow up',`<p class="boss-balance">${money(data.outstanding)}</p><p>Outstanding against issued invoices, after recorded collections and reversals.</p><p class="fine-print">Staff-entered records; no bank or payment-provider verification.</p>${link('/distributor/accounts','Review invoices '+icon('arrow'),'btn secondary')}`):''}${!(data.priorities||[]).some(group=>group.items.length)?'<p class="info-callout">No dated follow-ups, delayed work or service issues appear in these lists. Review your customer enquiries and quotations for other pending work.</p>':''}<div class="boss-priorities">${(data.priorities||[]).filter(group=>group.items.length).map(group=>section(e(group.title),group.items.length?group.items.map(item=>`<article class="boss-work"><div>${link(detail(group.kind,item.id),e(item.label),'text-link')}<small>${item.due_date?'Due '+e(item.due_date):'No follow-up date recorded'}</small></div>${link(detail(group.kind,item.id),'Open '+icon('arrow'),'btn secondary')} </article>`).join(''):'<p class="muted">No matching work is recorded.</p>')).join('')}</div><details class="boss-counts"><summary>More business information</summary><div class="ops-metrics">${cards.map(metric).join('')}</div></details>${section('Recent business activity',data.events.map(x=>`<p>${link(detail(x.record_type,x.record_id),e(x.action.replaceAll('_',' ')),'text-link')}<small class="ops-time">${when(x.created_at)}</small></p>`).join('')||'<p class="muted">No business activity is recorded yet.</p>')}${nav()}`;
 });}
 function customerPage(pth,kind){return A().resource(pth,base()+'/list/'+kind+'?page='+(p().get('page')||1),data=>`${heading('YOUR ENERGY JOURNEY',defs[kind][0],'Your linked records. Orders require explicit agreement; completion does not imply payment.')}${nav()}<div class="ops-records">${data.items.map(r=>summary(kind,r)).join('')}</div>${data.items.length?'':empty('No linked '+defs[kind][0].toLowerCase()+' yet.')}${pager(data)}`);}
 function customerActions(kind,r){if(kind==='orders')return (r.status==='awaiting_confirmation'&&r.acceptance_mode==='in_app'&&!r.customer_confirmed_at?form('/orders/'+r.id+'/confirm',hidden('revision',r.revision)+'<label class="checkbox-label"><input type="checkbox" name="confirmTerms" required> I confirm the displayed quotation revision, commercial terms, quantities, tax treatment and addresses.</label><p class="fine-print">The distributor must still accept the order explicitly. This confirmation does not make or authorize a payment.</p>','Confirm these exact commercial terms'):'<p>The order status reflects recorded customer and distributor actions.</p>')+(['confirmed','processing','partially_fulfilled','fulfilled'].includes(r.status)?form('/orders/'+r.id+'/service',operation()+text('Describe the service issue','issue','',true)+priority(),'Report a service issue'):'');return '<p>Recorded updates appear in this view. Contact the distributor to clarify missing terms. Warranty and external approvals are not assumed.</p>';}
 function notifications(pth){return A().resource(pth,base()+'/notifications?page='+(p().get('page')||1),data=>`${heading('IN-APP UPDATES','Notifications',`${data.unread} unread stored updates. No email, SMS or WhatsApp delivery is claimed.`)}${nav()}${link('/customer/reminders','My reminder preferences','btn secondary')}${data.items.map(n=>`<article class="panel ops-record"><div><h2>${e(n.message)}</h2>${n.read_at?'':status('Unread','gold')}<small>${when(n.created_at)}</small></div><div>${link(n.source==='workflow'?(customer()?'/customer/':'/distributor/')+(n.version_id?'quotation?id='+n.version_id:'enquiry?id='+n.enquiry_id):detail(n.record_type,n.record_id),'Open record','btn secondary')}${n.read_at?'':form('/notifications/'+n.source+'/'+n.id+'/read','','Mark as read')}</div></article>`).join('')||empty('No notifications yet.')}${pager(data)}`);}
 function page(pth){if(pth==='/distributor/dashboard')return dashboard(pth);if(pth.endsWith('/notifications')&&['/distributor/notifications','/customer/notifications'].includes(pth))return notifications(pth);if(pth==='/distributor/new')return createPage();if(['/distributor/record','/customer/business-record'].includes(pth))return recordPage(pth);for(const [kind,def] of Object.entries(defs))if(pth===def[3])return list(pth,kind);for(const [kind,url] of Object.entries(customerList))if(pth===url)return customerPage(pth,kind);return null;}
 async function changed(result,target){await A().refresh();A().setMessage(result.message||'Saved.');A().navigate(target||location.hash.slice(1));}
 function run(work,f){void A().run(async()=>{try{if(f.dataset.user!==A().user?.id||f.dataset.company&&f.dataset.company!==A().activeCompany?.id)throw new Error('Your account or active company changed. Refresh before continuing.');if(!navigator.onLine)throw new Error('You are offline. Keep this form open and reconnect before submitting; offline synchronization is not available.');await work();}catch(error){const box=f.querySelector('.ops-feedback');if(box){box.textContent=error.message;box.setAttribute('role','alert');box.tabIndex=-1;box.focus();}throw error;}},f);}
 const pickerChoices=new Map();
 async function picker(button){const container=button.closest('.ops-picker'),type=container.dataset.option,content=container.querySelector('.ops-picker-content'),f=button.closest('form');if(button.hasAttribute('data-ops-pick-clear')){container.querySelector('input[type=hidden]').value='';container.querySelector('.ops-picked').textContent='Not selected';content.innerHTML='';return;}if(button.dataset.opsPickValue){const option=pickerChoices.get(button.dataset.opsPickValue);container.querySelector('input[type=hidden]').value=option.id;container.querySelector('.ops-picked').textContent=option.label;content.innerHTML='';return;}if(button.hasAttribute('data-ops-pick-open'))content.innerHTML='<label>Search saved records<input class="ops-picker-search" type="search" maxlength="100"></label><button type="button" class="btn secondary" data-ops-pick-search="1">Search</button><div class="ops-picker-results" aria-live="polite"></div>';
 const page=Number(button.dataset.opsPickSearch||1),search=content.querySelector('.ops-picker-search').value;run(async()=>{const result=await A().api(type==='products'?'/public/products?'+new URLSearchParams({search,page}):'/companies/current/operations/options?'+new URLSearchParams({type,search,page}));if(!content.isConnected)return;const rows=result.items.map(r=>({id:r.id,label:r.label||r.name,role:r.role}));for(const r of rows)pickerChoices.set(r.id,r);content.querySelector('.ops-picker-results').innerHTML=rows.map(r=>`<div class="ops-option"><span>${e(r.label)}${r.role?' · '+e(r.role.replaceAll('_',' ')):''}</span><button type="button" class="btn secondary" data-ops-pick-value="${e(r.id)}">Choose</button></div>`).join('')+(rows.length?'':'<p>No matching records. Create the required record in its module first.</p>')+`<div class="purchase-nav">${page>1?`<button type="button" class="btn secondary" data-ops-pick-search="${page-1}">Previous</button>`:''}${page*result.pageSize<result.total?`<button type="button" class="btn secondary" data-ops-pick-search="${page+1}">Next</button>`:''}</div>`;},f);}
 document.addEventListener('submit',event=>{const f=event.target;if(!f.matches('.ops-form'))return;event.preventDefault();const data=Object.fromEntries(new FormData(f));run(async()=>{if(f.dataset.filter){const q=new URLSearchParams();for(const [key,value] of Object.entries(data))if(value)q.set(key,value);if(p().get('view'))q.set('view',p().get('view'));A().navigate(path()+'?'+q);return;}if('revision'in data)data.revision=Number(data.revision);if(f.elements.confirmTerms)data.confirmTerms=f.elements.confirmTerms.checked;if(f.dataset.kind==='orders'){const manual=f.elements.orderSource.value==='manual',group=f.querySelector('.ops-manual-agreement');data.commercial=manual?Object.fromEntries(['taxMode','delivery','installation','chargesTaxRate','included','excluded','warranty','timeframe','paymentTerms','assumptions','installationScope'].map(key=>[key,group.querySelector(`[name="${key}"]`).value])):null;if(manual){data.quotationId='';data.commercial.items=[...group.querySelectorAll('.ops-agreement-line')].map(row=>Object.fromEntries([...row.querySelectorAll('input[name],select[name]')].map(input=>[input.name,input.value])));}for(const input of group.querySelectorAll('[name]'))if(input.name!=='contactId')delete data[input.name];if(!manual)data.contactId='';delete data.orderSource;}if(f.dataset.kind==='purchases'){data.items=[...f.querySelectorAll('.ops-po-line')].map(row=>Object.fromEntries([...row.querySelectorAll('input[name]')].map(input=>[input.name,input.value])));for(const key of ['itemId','quantity','unitPrice','taxRate'])delete data[key];}if(f.elements.confirmCustomerAccess)data.confirmCustomerAccess=f.elements.confirmCustomerAccess.checked;const result=await A().api(base()+f.dataset.endpoint,'POST',data);if(result.shareUrl)Organization.setInvitationReceipt(result);await changed(result,f.dataset.kind&&result.id?detail(f.dataset.kind,result.id):customer()&&f.dataset.endpoint.endsWith('/service')&&result.id?detail('service',result.id):null);},f);});
 document.addEventListener('change',event=>{if(event.target.name!=='orderSource')return;const f=event.target.form,manual=event.target.value==='manual',group=f.querySelector('.ops-manual-agreement');group.hidden=!manual;group.disabled=!manual;f.querySelector('.ops-quote-source').hidden=manual;});
 document.addEventListener('input',event=>{const f=event.target.closest('.ops-form');if(f?.dataset.kind==='orders')previewAgreement(f);});
 document.addEventListener('click',event=>{const agreedAdd=event.target.closest('[data-ops-agreement-add]'),agreedRemove=event.target.closest('[data-ops-agreement-remove]');if(agreedAdd){if(agreedAdd.form.querySelectorAll('.ops-agreement-line').length>=20){announce('Use at most twenty agreed lines.');return;}agreedAdd.form.querySelector('#ops-agreement-lines').insertAdjacentHTML('beforeend',agreementLine());return;}if(agreedRemove){const f=agreedRemove.form;if(f.querySelectorAll('.ops-agreement-line').length<2){announce('Keep at least one line.');return;}agreedRemove.closest('.ops-agreement-line').remove();previewAgreement(f);return;}const button=event.target.closest('[data-ops-pick-open],[data-ops-pick-clear],[data-ops-pick-search],[data-ops-pick-value]');if(button){void picker(button);return;}const add=event.target.closest('[data-ops-po-add]'),remove=event.target.closest('[data-ops-po-remove]');if(add){if(add.form.querySelectorAll('.ops-po-line').length>=20){announce('Add at most twenty lines.');return;}add.form.querySelector('#ops-po-lines').insertAdjacentHTML('beforeend',purchaseLine());}if(remove){if(remove.form.querySelectorAll('.ops-po-line').length<2){announce('Keep at least one purchase line.');return;}remove.closest('.ops-po-line').remove();}});
 window.addEventListener('offline',()=>{const f=document.querySelector('.ops-form');if(f)f.querySelector('.ops-feedback').textContent='You are offline. Keep this form open and reconnect before submitting. No offline synchronization is implemented.';});
